async function testSnakeGame() {
    console.log('=== 贪吃蛇游戏自动化测试 ===\n');

    let browser;
    let context;
    let page;

    try {
        // 连接到现有的CDP浏览器实例
        console.log('步骤1: 连接到CDP浏览器 (http://127.0.0.1:9222)...');
        browser = await playwright.chromium.connectOverCDP('http://127.0.0.1:9222');
        console.log('✓ 成功连接到CDP浏览器\n');

        // 获取现有的上下文
        const contexts = browser.contexts();
        if (contexts.length > 0) {
            context = contexts[0];
            console.log('✓ 复用现有浏览器上下文\n');
        } else {
            console.log('✗ 未找到现有上下文，创建新上下文');
            context = await browser.newContext();
        }

        // 获取或创建页面
        const pages = context.pages();
        if (pages.length > 0) {
            page = pages[0];
            console.log('✓ 复用现有页面\n');
        } else {
            console.log('创建新页面...');
            page = await context.newPage();
            console.log('✓ 创建新页面成功\n');
        }

        // 导航到游戏页面
